    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('findUser returns null for an unknown id', (t, done) => {
  findUser(999, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

test('findUser returns a matching user', (t, done) => {
  findUser(1, (err, user) => {
    assert.equal(err, null);
    assert.equal(user.id, 1);
    done();
  });
});

test('softDeleteUser returns the updated user and excludes it from active users', async () => {
  const deleteUser = promisify(softDeleteUser);
  const activeUsers = promisify(listActiveUsers);
  try {
    const user = await deleteUser(2, '2026-10-22');
    assert.equal(user.deleted_at, '2026-10-22');
    assert.ok((await activeUsers()).every((activeUser) => activeUser.id !== 2));
  } finally {
    await deleteUser(2, null);
  }
});

test('softDeleteUser passes repository errors to the callback', (t, done) => {
